Definition pkcs7_cinfo_postA (segs : list Segment) (R : art_layout) (HIA : artA segs R)
    (h : HST segs R HIA) (LB LF : list blk)
    (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (PP SEQE BS P END lo slo : Z) (pad : word) (m0 : mem) : machine_state -> Prop :=
  fun ms' => exists t0' t1' t2' a0 a1 a2 a3 a4 a5 a6 a7 t3' t4' t5' t6' m' h' (r p' se : Z) (tg : word) (len q : Z),
    ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6')
             F (ret_pc ra) fc None m' (seg_rom segs)
    /\ HM segs R HIA h' LB LF m' /\ hcs segs R HIA h' = hcs segs R HIA h /\ htop segs R HIA h' = htop segs R HIA h
    /\ hstkhi segs R HIA h' = hstkhi segs R HIA h /\ hflag segs R HIA h' = hflag segs R HIA h
    /\ havol segs R HIA h' = havol segs R HIA h /\ hfr segs R HIA h' = hfr segs R HIA h   (* [comment removed for export] *)
    /\ (forall mo, HK segs R HIA h' mo <-> HK segs R HIA h mo)
    /\ presA segs R LB LF (bv_unsigned sp) (bv_unsigned sp) (hstkhi segs R HIA h) [(PP, PP + 8); (SEQE, SEQE + 8); (BS, BS + 24)] m0 m'
    /\ mem_inv segs m' /\ stk segs m' lo (bv_unsigned sp) /\ sshad segs (arl_AL R) m' slo (bv_unsigned sp)
    /\ a0 = Z_to_bv 64 r /\ (-0x5600 < r <= 0)
    /\ rw_cells segs m' PP [C8 (Z_to_bv 64 p')]
    /\ rw_cells segs m' SEQE [C8 (Z_to_bv 64 se)]
    /\ rw_cells segs m' BS (buf_cells tg pad len q)
    /\ P <= p' <= END
    /\ (r = 0 -> tg = Z_to_bv 64 6 /\ P + 4 <= q /\ 0 <= len /\ q + len = p' /\ p' <= se <= END).

Definition pkcs7_cinfo_stmtA (segs : list Segment) (R : art_layout) (HIA : artA segs R) (ENTRY : Z) : Prop :=
  forall (h : HST segs R HIA) (LB LF : list blk)
         (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
         (F : bvmap 5 word) (fc : bv 32) (m : mem)
         (PP SEQE BS P END BUF lo slo : Z) (bs : list byte) (sev tg0 pad : word) (len0 q0 : Z),
  HM segs R HIA h LB LF m -> (length LF < 512)%nat ->                                                (* [comment removed for export] *)
  rw_cells segs m PP [C8 (Z_to_bv 64 P)] -> rw_cells segs m SEQE [C8 sev] ->
